#!/usr/bin/env python3
"""Small pure-Python implementation of the GNU sed subset used by this image."""
import sys, re

ESC = {'a':'\a','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v'}
CLASSES = {
 'alnum':'A-Za-z0-9','alpha':'A-Za-z','blank':' \t','cntrl':'\x00-\x1f\x7f',
 'digit':'0-9','graph':'!-~','lower':'a-z','print':' -~','punct':r'!-/:-@\[-`{-~',
 'space':' \t\r\n\v\f','upper':'A-Z','xdigit':'A-Fa-f0-9'
