    if j<len(src) and src[j]==']': body+=r'\]'; j+=1
    while j<len(src):
        if src[j]==']': return '['+neg+body+']',j+1
        if src.startswith('[:',j):
            k=src.find(':]',j+2)
            if k>=0 and src[j+2:k] in CLASSES:
                body+=CLASSES[src[j+2:k]]; j=k+2; continue
