            d=src[j+1]
            if d in ESC: body+=re.escape(ESC[d]); j+=2; continue
            if d in 'wWsS':
                vals={'w':'A-Za-z0-9_','W':'^A-Za-z0-9_','s':' \t\r\n\v\f','S':'^ \t\r\n\v\f'}
                body+=vals[d]; j+=2; continue
