            elif d=='S': out+='[^ \t\r\n\v\f]'
            elif d=='b': out+=r'(?<![A-Za-z0-9_])(?=[A-Za-z0-9_])|(?<=[A-Za-z0-9_])(?![A-Za-z0-9_])'
