class RX:
    def __init__(self, raw, ext):
        self.raw=raw; self.py=regex_translate(raw,ext)
        try: self.base=re.compile(self.py, re.ASCII)
        except re.error: self.base=re.compile(r'(?!x)x')
    def match(self,text,start=0):
        # POSIX leftmost-longest. Appending a lookahead for the exact remaining
        # length forces Python's alternation engine to backtrack to a longer arm.
        n=len(text)
        for a in range(start,n+1):
            for b in range(n,a-1,-1):
                tail=n-b
                try: rr=re.compile('(?:'+self.py+')(?=[\\s\\S]{'+str(tail)+'}\\Z)',re.ASCII)
                except re.error: return None
                m=rr.match(text,a)
                if m is not None and m.end()==b: return m
        return None

class Addr:
    def __init__(self,kind,val=None): self.kind=kind; self.val=val
    def hit(self,ctx):
        if self.kind=='num': return ctx.lineno==self.val
        if self.kind=='last': return ctx.last
        if self.kind=='step':
            first,step=self.val
            return ctx.lineno>=first and (ctx.lineno-first)%step==0
        if self.kind=='rx': return ctx.rxhit(self.val)
        return False

class Cmd:
    def __init__(self,a1=None,a2=None,neg=False,op='',arg=None):
        self.a1=a1; self.a2=a2; self.neg=neg; self.op=op; self.arg=arg
