        if not self.a1: h=True
        elif not self.a2: h=self.a1.hit(ctx)
        elif self.a1.kind=='num' and self.a1.val==0:
            if not self.active: self.active=True
            h=True
            if self.a2.hit(ctx): self.active=False
        elif self.active:
            h=True
            if self.a2.kind=='plus':
                if ctx.lineno>=self.a2.val: self.active=False
            elif self.a2.kind=='tilde':
                if ctx.lineno%self.a2.val==0: self.active=False
            elif self.a2.hit(ctx): self.active=False
        elif self.a1.hit(ctx):
            h=True; self.active=True
            if self.a2.kind=='plus': self.a2.val=ctx.lineno+self.a2.val
            if self.a2.kind not in ('plus','tilde') and self.a2.hit(ctx): self.active=False
        else: h=False
        return not h if self.neg else h

class Parser:
 def __init__(self,s,ext): self.s=s; self.i=0; self.ext=ext; self.cmds=[]
 def ws(self):
    while self.i<len(self.s) and self.s[self.i] in ' \t\r': self.i+=1
 def delimited(self,delim):
    out=''
