        n=int(self.s[j:self.i])
        if self.i<len(self.s) and self.s[self.i]=='~':
            self.i+=1; j=self.i
            while self.i<len(self.s) and self.s[self.i].isdigit(): self.i+=1
            return Addr('step',(n,int(self.s[j:self.i])))
        return Addr('num',n)
    if c=='$': self.i+=1; return Addr('last')
    if c=='/': self.i+=1; return Addr('rx',RX(self.delimited('/'),self.ext))
    if c=='\\' and self.i+1<len(self.s):
        d=self.s[self.i+1]; self.i+=2
        return Addr('rx',RX(self.delimited(d),self.ext))
    return None
 def parse(self,stop=False):
    while self.i<len(self.s):
        self.ws()
        if self.i>=len(self.s): break
        if self.s[self.i] in ';\n': self.i+=1; continue
        if self.s[self.i]=='#':
            k=self.s.find('\n',self.i); self.i=len(self.s) if k<0 else k+1; continue
        if self.s[self.i]=='}':
            self.i+=1
            if stop:return
            continue
