        if rep[i]=='&':out+=m.group(0);i+=1
        elif rep[i]=='\\' and i+1<len(rep):
            d=rep[i+1]
            if d.isdigit() and d!='0':
                try: out+=m.group(int(d)) or ''
                except IndexError: pass
            elif d in ESC:out+=ESC[d]
            else:out+=d
            i+=2
        else:out+=rep[i];i+=1
    return out

def substitute(text,rx,rep,flags):
    nums=[int(x) for x in re.findall(r'\d+',flags)]; nth=nums[-1] if nums else 1
