    while pos<=len(text):
        m=rx.match(text,pos)
        if not m:break
        matches.append(m)
        pos=m.end() if m.end()>m.start() else m.end()+1
    chosen=[]
    for k,m in enumerate(matches,1):
        if (glob and k>=nth) or (not glob and k==nth):chosen.append(m)
    if not chosen:return text,False
    out='';pos=0
    for m in chosen:out+=text[pos:m.start()]+replacement(rep,m);pos=m.end()
    return out+text[pos:],True

