    idx=0; exitcode=0; quitall=False
    while idx<len(records) and not quitall:
        source,text,lastsrc=records[idx]
        if separate and (idx==0 or records[idx-1][0]!=source):
            ctx.lineno=0
            for c in cmds:c.active=False
        ctx.lineno+=1;ctx.ps=text;ctx.last=(idx==len(records)-1) if not separate else lastsrc
        idx+=1; pc=0; deleted=False; queue=[]; subst=False
        while pc<len(cmds):
            c=cmds[pc]
            if c.op=='{' and not c.selected(ctx):pc=c.arg;continue
            if c.op!='{' and not c.selected(ctx):pc+=1;continue
            op=c.op
            if op in ('',':','{'):pass
            elif op=='p':out.append(ctx.ps+'\n')
            elif op=='P':out.append(ctx.ps.split('\n',1)[0]+'\n')
            elif op=='=':out.append(str(ctx.lineno)+'\n')
            elif op=='d':deleted=True;break
            elif op=='D':
                if '\n' in ctx.ps:ctx.ps=ctx.ps.split('\n',1)[1];pc=0;continue
                deleted=True;break
            elif op=='h':hold=ctx.ps
            elif op=='H':hold+='\n'+ctx.ps
            elif op=='g':ctx.ps=hold
            elif op=='G':ctx.ps+='\n'+hold
            elif op=='x':ctx.ps,hold=hold,ctx.ps
            elif op=='z':ctx.ps=''
            elif op=='i':out.append(c.arg+'\n')
            elif op=='a':queue.append(c.arg+'\n')
            elif op=='c':
                # For ranges GNU emits text only when the range closes (or for a singleton).
                if not c.a2 or not c.active:out.append(c.arg+'\n')
                deleted=True;break
            elif op=='s':
                ctx.ps,ok=substitute(ctx.ps,*c.arg[:2],c.arg[2]);subst|=ok
                if ok and 'p' in c.arg[2]:out.append(ctx.ps+'\n')
            elif op in ('b','t','T'):
                take=op=='b' or (op=='t' and subst) or (op=='T' and not subst)
                if op in 'tT':subst=False
                if take:
                    if c.arg=='':break
                    pc=labels.get(c.arg,len(cmds));continue
            elif op=='n':
                if not quiet:out.append(ctx.ps+'\n')
                out.extend(queue);queue=[]
                if idx>=len(records):deleted=True;break
                source,text,lastsrc=records[idx];idx+=1;ctx.lineno+=1;ctx.ps=text
                ctx.last=(idx==len(records)) if not separate else lastsrc;subst=False
            elif op=='N':
                if idx>=len(records):break
                source,text,lastsrc=records[idx];idx+=1;ctx.lineno+=1;ctx.ps+='\n'+text
                ctx.last=(idx==len(records)) if not separate else lastsrc;subst=False
            elif op in ('q','Q'):
                if op=='q' and not quiet:out.append(ctx.ps+'\n')
