def main(argv):
    quiet=False;ext=False;sep=False;pieces=[];i=0
    while i<len(argv) and argv[i].startswith('-') and argv[i]!='-':
        a=argv[i]
        if a=='-n':quiet=True
        elif a=='-E':ext=True
        elif a=='-s':sep=True
        elif a=='-e':
            i+=1
            if i>=len(argv):return 1
            pieces.append(argv[i])
        else:return 1
        i+=1
    if not pieces:
        if i>=len(argv):return 1
        pieces=[argv[i]];i+=1
    script='\n'.join(pieces)
    if script.startswith('#n'):quiet=True
    cmds=Parser(script,ext).parse()
    files=argv[i:]; records=[];status=0
    if not files:
        data=sys.stdin.buffer.read().decode('latin1'); lines=data.splitlines(True)
        vals=[x[:-1] if x.endswith('\n') else x for x in lines]
        records=[('<stdin>',x,j==len(vals)-1) for j,x in enumerate(vals)]
    else:
        for fi,name in enumerate(files):
            try:data=open(name,'rb').read().decode('latin1')
            except OSError:status=2;continue
            lines=data.splitlines(True);vals=[x[:-1] if x.endswith('\n') else x for x in lines]
            records += [(fi,x,j==len(vals)-1) for j,x in enumerate(vals)]
    text,code=run(cmds,records,quiet,sep)
    sys.stdout.buffer.write(text.encode('latin1'))
    return code if code else status
